style.css:
@-moz-document domain("shopee.com.br") {
/* fundo */
body {
    background-color: #fff5f7 !important;
}

/* header */
header {
    background-color: #ffeef2 !important;
}

/* cards de produtos */
div[data-sqe="item"] {
    background-color: rgba(255, 255, 255, 0.8);
    border-radius: 12px;
}

/* hover */
div[data-sqe="item"]:hover {
    background-color: rgba(255, 182, 193, 0.15);
}

/* textos */
span {
    color: #000 !important;
}
}
